begin;
create function internal.read_class_learning_summary(target_class uuid,page_limit integer,page_cursor uuid)returns jsonb language plpgsql security definer set search_path=''as $$
declare school uuid:="authorization".school_id();role_name text;courses uuid[];person record;rows jsonb:='[]';items jsonb;academic jsonb;observed jsonb;support jsonb;outcomes jsonb;days integer;window_start timestamptz;window_end timestamptz;kind text;count_value integer;ids jsonb;
begin
 role_name:="authorization".current_role(school);
 if role_name not in('admin','coordinator','teacher')or not"authorization".has_entitlement(school,'learner.state')or not"authorization".academic_access(school)or not"authorization".has_entitlement(school,'improvement')or not"authorization".can_view_class(school,target_class)or not exists(select 1 from app.classes where school_id=school and id=target_class and status='active')then raise exception 'Class learning summary denied'using errcode='42501';end if;
 if page_limit is null or page_limit not between 1 and 100 then raise exception 'Bounded class page required'using errcode='22023';end if;
 select coalesce(array_agg(id),array[]::uuid[])into courses from app.courses where school_id=school and class_id=target_class and"authorization".can_read_course(school,id);
 select development_window_days into days from app.learner_state_policies where school_id=school;if days is not null then window_end:=clock_timestamp();window_start:=window_end-make_interval(days=>days);end if;
 for person in select member.actor_id,people.display_name from app.memberships member join app.enrollments enrollment on enrollment.school_id=member.school_id and enrollment.student_actor_id=member.actor_id join app.people people on people.school_id=member.school_id and people.actor_id=member.actor_id where member.school_id=school and member.role='student'and member.status='active'and member.effective_from<=now()and(member.effective_to is null or member.effective_to>now())and enrollment.class_id=target_class and enrollment.status='active'and enrollment.effective_from<=now()and(enrollment.effective_to is null or enrollment.effective_to>now())and(page_cursor is null or member.actor_id>page_cursor)order by member.actor_id limit page_limit+1 loop
  with sources as materialized(
   select result.id,result.evidence_id,result.reference_id,result.reference_version,result.created_at,'numeric'::text model,jsonb_build_object('type','numeric','score',result.score,'maxScore',result.max_score,'policyVersion',result.policy_version,'normalized',null)native
   from app.current_results current_source join app.result_revisions result on result.school_id=current_source.school_id and result.id=current_source.result_id join app.assessments assessment on assessment.school_id=result.school_id and assessment.id=result.assessment_id
   where result.school_id=school and result.learner_id=person.actor_id and assessment.course_id=any(courses)and"authorization".programme_course_allowed(school,assessment.course_id,person.actor_id)
   and exists(select 1 from app.academic_evidence evidence where evidence.school_id=school and evidence.id=result.evidence_id and evidence.result_id=result.id and evidence.learner_id=person.actor_id and evidence.source_object_id=result.submission_id)
   and exists(select 1 from app.school_custom_references reference join app.school_custom_versions version on version.school_id=reference.school_id and version.id=reference.version_id where reference.school_id=school and reference.id=result.reference_id and reference.status='APPROVED'and version.version=result.reference_version)
   union all
   select result.id,result.evidence_id,result.reference_id,result.reference_version,result.created_at,'rubric'::text,result.native_result from app.current_rubric_results current_source join app.rubric_result_revisions result on result.school_id=current_source.school_id and result.id=current_source.result_id join app.assessments assessment on assessment.school_id=result.school_id and assessment.id=result.assessment_id
   where result.school_id=school and result.learner_id=person.actor_id and assessment.course_id=any(courses)and"authorization".programme_course_allowed(school,assessment.course_id,person.actor_id)
   and exists(select 1 from app.rubric_evidence evidence where evidence.school_id=school and evidence.id=result.evidence_id and evidence.result_id=result.id and evidence.learner_id=person.actor_id and evidence.source_object_id=result.submission_id)
   and exists(select 1 from app.school_custom_references reference join app.school_custom_versions version on version.school_id=reference.school_id and version.id=reference.version_id where reference.school_id=school and reference.id=result.reference_id and reference.status='APPROVED'and version.version=result.reference_version)
  )select jsonb_build_object('numericCount',(select count(*)from sources where model='numeric'),'rubricCount',(select count(*)from sources where model='rubric'),'moreSources',(select count(*)>10 from sources),'sources',(select coalesce(jsonb_agg(jsonb_build_object('resultId',id,'evidenceId',evidence_id,'referenceId',reference_id,'referenceVersion',reference_version,'observedAt',created_at,'nativeResult',native)order by created_at desc,id),'[]'::jsonb)from(select*from sources order by created_at desc,id limit 10)bounded))into academic;
  observed:='{}';foreach kind in array array['practice','revision','reflection']loop
   if days is null then count_value:=null;ids:='[]';else
    with sources as materialized(select observation.id from app.habit_observations observation
     left join app.activity_completions completion on completion.school_id=observation.school_id and completion.id=observation.activity_completion_id
     left join app.activities activity on activity.school_id=completion.school_id and activity.id=completion.activity_id left join app.lessons lesson on lesson.school_id=activity.school_id and lesson.id=activity.lesson_id left join app.units unit on unit.school_id=lesson.school_id and unit.id=lesson.unit_id
     left join app.submissions submission on submission.school_id=observation.school_id and submission.id=observation.submission_id left join app.assessments assessment on assessment.school_id=submission.school_id and assessment.id=submission.assessment_id
     where observation.school_id=school and observation.learner_id=person.actor_id and observation.kind=kind and observation.occurred_at>=window_start and observation.occurred_at<=window_end and coalesce(unit.course_id,assessment.course_id)=any(courses)and"authorization".programme_course_allowed(school,coalesce(unit.course_id,assessment.course_id),person.actor_id))
    select(select count(*)from sources),(select coalesce(jsonb_agg(id order by id),'[]'::jsonb)from(select id from sources order by id limit 10)bounded)into count_value,ids;
   end if;observed:=observed||jsonb_build_object(kind,jsonb_build_object('count',count_value,'observationIds',ids,'moreSourceIds',coalesce(count_value>10,false)));
  end loop;
  with sources as materialized(select intervention.id,intervention.status from app.interventions intervention join app.result_revisions baseline on baseline.school_id=intervention.school_id and baseline.id=intervention.baseline_result_id join app.assessments assessment on assessment.school_id=baseline.school_id and assessment.id=baseline.assessment_id where intervention.school_id=school and intervention.learner_id=person.actor_id and assessment.course_id=any(courses)and"authorization".programme_course_allowed(school,assessment.course_id,person.actor_id))
  select jsonb_build_object('assignedCount',(select count(*)from sources where status='ASSIGNED'),'completedCount',(select count(*)from sources where status='COMPLETED'),'measuredCount',(select count(*)from sources where status='MEASURED'),'interventionIds',(select coalesce(jsonb_agg(id order by id),'[]'::jsonb)from(select id from sources order by id limit 10)bounded))into support;
  with sources as materialized(select outcome.id,outcome.status from app.outcome_measurements outcome join app.interventions intervention on intervention.school_id=outcome.school_id and intervention.id=outcome.intervention_id join app.result_revisions baseline on baseline.school_id=intervention.school_id and baseline.id=intervention.baseline_result_id join app.assessments assessment on assessment.school_id=baseline.school_id and assessment.id=baseline.assessment_id where outcome.school_id=school and outcome.learner_id=person.actor_id and assessment.course_id=any(courses)and"authorization".programme_course_allowed(school,assessment.course_id,person.actor_id))
  select jsonb_build_object('improvedCount',(select count(*)from sources where status='improved'),'noMeaningfulChangeCount',(select count(*)from sources where status='no_meaningful_change'),'inconclusiveCount',(select count(*)from sources where status='inconclusive'),'measurementIds',(select coalesce(jsonb_agg(id order by id),'[]'::jsonb)from(select id from sources order by id limit 10)bounded))into outcomes;
  rows:=rows||jsonb_build_array(jsonb_build_object('learnerId',person.actor_id,'learnerName',person.display_name,'academic',academic,'observed',observed,'support',support,'outcomes',outcomes));
  if octet_length(rows::text)>500000 then raise exception 'Class summary requires a smaller page'using errcode='22023';end if;
 end loop;
 select coalesce(jsonb_agg(item order by ordinal),'[]'::jsonb)into items from jsonb_array_elements(rows)with ordinality value(item,ordinal)where ordinal<=page_limit;
 return jsonb_build_object('schoolId',school,'classId',target_class,'generatedAt',clock_timestamp(),'scope','CURRENT_CLASS_PAGE','coverage','NOT_ESTABLISHED','observationCoverage','RECORDED_ONLY','windowStart',window_start,'windowEnd',window_end,'items',items,'nextCursor',case when jsonb_array_length(rows)>page_limit then items->(page_limit-1)->>'learnerId'else null end);
end$$;
revoke execute on function internal.read_class_learning_summary(uuid,integer,uuid)from public,anon,authenticated,service_role,cuevo_api,cuevo_worker;
grant execute on function internal.read_class_learning_summary(uuid,integer,uuid)to cuevo_api;
commit;
